import{_ as e,o as l,c as o,at as t}from"./chunks/framework.CY22Hent.js";const r="/assets/ruankao_2026-08-26_212614_394.CLXb5hkt.png",i="/assets/ruankao_2026-08-26_214932_098.CJNRwLM1.png",q=JSON.parse('{"title":"系统分析师笔记10_系统规划与分析","description":"","frontmatter":{"title":"系统分析师笔记10_系统规划与分析","date":"2026-08-26T00:00:00.000Z","lastUpdated":"2026-08-26T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/系统分析师笔记10_系统规划与分析.md","filePath":"blogs/软考/系统分析师笔记10_系统规划与分析.md"}'),h={name:"blogs/软考/系统分析师笔记10_系统规划与分析.md"};function p(n,a,d,c,u,s){return l(),o("div",null,[...a[0]||(a[0]=[t('<p>[toc]</p><h1 id="系统分析师笔记10-系统规划与分析" tabindex="-1">系统分析师笔记10_系统规划与分析 <a class="header-anchor" href="#系统分析师笔记10-系统规划与分析" aria-label="Permalink to &quot;系统分析师笔记10_系统规划与分析&quot;">​</a></h1><p>该笔记内容来自《系统分析师教程》第2版。</p><p>系统规划是信息系统生命周期的第一个阶段，其任务是对企业的环境、目标及现有系统的状况进行初步调查，根据企业目标和发展战略，确定信息系统的发展战略，对建设新系统的需求做出分析和预测，同时考虑建设新系统所受的各种约束，研宄建设新系统的必要性和可能性。</p><p>系统规划可以减少盲目 性，使系统具有良好的整体性、较高的适应性，建设工作有良好的阶段性，以缩短系统开发周期，节约开发费用。因此，系统规划是信息系统建设成功的关键，它比具体项目的开发更为重要。</p><h2 id="系统规划概述" tabindex="-1">系统规划概述 <a class="header-anchor" href="#系统规划概述" aria-label="Permalink to &quot;系统规划概述&quot;">​</a></h2><blockquote><p>系统规划的主要步骤</p></blockquote><p>根据系统规划的主要任务，可以按照以下步骤开展系统规划工作:</p><ul><li>(1)对现有系统进行初步调查。根据企业战略和发展目标，从类似企业和本企业内部收集各种信息，站在管理层的高度观察企业的现状，分析现有系统的运行状况。</li><li>(2)分析和确定系统目标。系统目标应包括服务的质量和范围、政策、组织和人员等，它不仅包括信息系统的目标，还要反映整个企业的目标。</li><li>(3)分析子系统的组成和基本功能。自顶向下对系统进行划分，并且详细说明各个子系统应该实现的功能。</li><li>(4)拟定系统的实施方案。可以对子系统的优先级进行设定，以便确定子系统的开发顺序。</li><li>(5)进行系统的可行性研究。编写可行性研究报告，召开可行性论证会。</li><li>(6)制定系统建设方案。对可行性研究报告中提出的各项技术指标进行分析、比较，落实各项假设的前提条件，制定系统建设方案，并根据该方案及其实施计划编写成系统设计任务书。系统设计任务书经上级主管部门批准后，正式作为系统建设的依据。</li></ul><h2 id="项目的提出和选择" tabindex="-1">项目的提出和选择 <a class="header-anchor" href="#项目的提出和选择" aria-label="Permalink to &quot;项目的提出和选择&quot;">​</a></h2><h3 id="项目的立项目标和动机" tabindex="-1">项目的立项目标和动机 <a class="header-anchor" href="#项目的立项目标和动机" aria-label="Permalink to &quot;项目的立项目标和动机&quot;">​</a></h3><p>企业在运营和管理过程中，对于信息系统项目的建设可能具有多种动机，通常可归结为4种模式，分别是进行基础研宄、进行应用研发、提供技术服务和产品的使用者。</p><blockquote><p>进行基础研究</p></blockquote><p>此类项目通常由大学、科研院所、企业集团从事基础研究的部门提出和实施。</p><p>基础研究通常都被看作是一种长期的战略性投资，目标不是为了短期的市场收益和支持当前的市场或行业应用，而是为了开拓未来的市场，创造全新概念的产品、产业或生活方式，建立企业、行业甚至国家的竞争优势。</p><blockquote><p>进行应用研发</p></blockquote><p>此类项目通常由企业进行立项和开发，企业立项的基本动机是得到应用产品，并向目标客户群进行销售，从而占有市场份额并获取利润。</p><p>产品一般会基于某类特定客户群体的需求进行设计，有明确和具体的研发目标需求，有严格的时间限制和资源预算，大多以项目方式进行 组织。</p><blockquote><p>提供技术服务</p></blockquote><p>对此类项目进行立项的企业通常能向目标客户群提供比较全面的技术服务，而不是单一的软件产品。服务范围可能包括提供技术和解决方案的咨询、利用现有产品进行系统集成和服务、面向特定客户的项目定制开发、对现有系统进行升级和改造、提供系统应用相关的技 术支持、服务和培训等，一个企业可以提供其中的一项或多项内容。</p><blockquote><p>产品的使用者</p></blockquote><p>产品的使用者是系统的最终用户。对他们来说，项目的立项动机既不是得到产品进行销售，也不是为了提供技术服务，而是通过采购产品或技术服务来得到使用价值。</p><p>例如，个人消费者购买绘图软件是为了存储和处理个人数码相机中的照片，企业通过部署ERP系统可能是为了达到科学计划生产、提高管理水平、降低库存成本、提高资金周转率等目标，并期望通过这些目标的实现来增强企业竞争力，获取更大的市场份额。</p><h3 id="项目立项的价值判断" tabindex="-1">项目立项的价值判断 <a class="header-anchor" href="#项目立项的价值判断" aria-label="Permalink to &quot;项目立项的价值判断&quot;">​</a></h3><p>项目提出后，能否达成一个成功的立项，取决于人们对项目收益预期的价值判断。不同类型的信息系统项目立项，具有截然不同的价值观和侧重点。</p><p>通常，以基础研究为目标的项目是高度技术研究导向的，以应用产品开发为目标的项目重点关注的是技术在具体领域中的应用和推广，以技术服务为目标的项目则是高度客户业务导向或客户满意导向的，产品的最终用户则主要关注系统的使用、影响和代价等应用性问题。</p><h3 id="项目的选择和确定" tabindex="-1">项目的选择和确定 <a class="header-anchor" href="#项目的选择和确定" aria-label="Permalink to &quot;项目的选择和确定&quot;">​</a></h3><p>项目建议提出来后，就需要对项目进行选择和确定。</p><p>在实际工作中，并不存在一个统一的模式进行项目的选择和取舍，但存在一些进行项目评估的基本原则，通过使用这些原则，可以逐步排除那些不符合需求的建议项目，选择和确定满意的项目。</p><blockquote><p>选择有核心价值的项目</p></blockquote><p>这个策略的关键在于确定什么样的项目是有价值的。由于立项单位所处的行业、在行业中的位置和立项目标等因素不同，对信息系统项目的价值判断也有所不同。</p><p>但是，一般来说，有 核心价值的项目总是和企业的核心业务相关的，也可以说，信息化的关键就是核心业务的信息化。</p><blockquote><p>评估所选择的项目</p></blockquote><p>在判断出一个具有潜在价值的项目后，还应评估项目实施的约束、风险、成本和效益。通常，这部分内容可以在项目的可行性研究工作中完成。</p><blockquote><p>项目优先级排序</p></blockquote><p>经过项目评估后，如果还有多个建议项目，但企业资源有限，不可能同时建设这些项目，就需要对已选择的项目进行优先级排序，合理使用企业资源，使资源得到最优配置。</p><p>具体的 排序方法是根据企业已有资源情况，进行项目的成本效益分析，考察净现值、投资回收期等指标。</p><blockquote><p>评估项目的多种实施方式</p></blockquote><p>对于已经确认有价值并且有能力开发的项目，则可以进一步参照企业现状，考察项目的实施方式。这个过程一般由项目的负责人和企业中高层经理进行决策。</p><blockquote><p>平衡地选择合适的方案</p></blockquote><p>事实上，对系统功能和性能的要求常常是充满矛盾的，任何时候都不存在一个完美无缺 的方案，只存在一个对当前的项目目标相对比较合适的方案。选择项目的基本原则应该是“合 适”，而不是尽可能的“好”。</p><p>实际上，任何超出预期设定目标的“好”性能，通常都意味着某方面更多的成本或者潜在的风险。</p><h2 id="系统分析概述" tabindex="-1">系统分析概述 <a class="header-anchor" href="#系统分析概述" aria-label="Permalink to &quot;系统分析概述&quot;">​</a></h2><h3 id="系统分析的任务" tabindex="-1">系统分析的任务 <a class="header-anchor" href="#系统分析的任务" aria-label="Permalink to &quot;系统分析的任务&quot;">​</a></h3><p>系统分析阶段的基本任务是系统分析师和用户在充分了解用户需求的基础上，把双方对新系统的理解表达为系统需求规格说明书。</p><p>系统分析师要在系统规划的基础上，与用户密切配合，用系统的思想和方法，对企业的业务活动进行全面的调查分析，详细掌握有关的工作流程，收集与系统有关的各种资料，分析现有系统的局限性和不足之处，找出制约现有系统的瓶颈，确定新系统的逻辑功能。</p><h3 id="系统分析的难点" tabindex="-1">系统分析的难点 <a class="header-anchor" href="#系统分析的难点" aria-label="Permalink to &quot;系统分析的难点&quot;">​</a></h3><p>系统分析阶段的难点主要包括以下三个方面：</p><ul><li>(1)系统分析师与用户对系统的理解不同。一方面，系统分析师通常是IT专家，但缺乏足够的用户业务领域的知识，系统分析师在分析过程中往往被各种信息流程所淹没，难以厘清头绪，更难以分析出制约现有系统的瓶颈问题：另一方面，用户精通业务，但通常缺乏足够的IT知识。对于一些具体的业务，用户往往认为这是理所当然的，因此无须介绍。但事实上，系统分析师却难以理解。</li><li>(2)系统分析师与用户沟通困难。系统分析师与用户所处行业不同，知识结构不同，经历不同，使得双方的交流十分困难。这样，就容易导致系统调查出现遗漏和误解。这些遗漏和误解就是系统的隐患，会使系统开发偏离正确的方向。</li><li>(3)环境的不断变化。系统分析阶段要通过调查分析，抽象出新系统的逻辑模型，锁定系统边界、功能、处理过程和信息结构，为系统设计奠定基础。但是，企业内、外部环境总在不断地发生变化，对信息系统提出新的要求。只有适应这些要求，信息系统才能生存下去。 能的。</li></ul><h2 id="问题分析" tabindex="-1">问题分析 <a class="header-anchor" href="#问题分析" aria-label="Permalink to &quot;问题分析&quot;">​</a></h2><h3 id="研究问题的领域" tabindex="-1">研究问题的领域 <a class="header-anchor" href="#研究问题的领域" aria-label="Permalink to &quot;研究问题的领域&quot;">​</a></h3><p>在问题分析阶段，项目团队首先试图了解当前系统。每个系统所有者、用户和分析员对系统具有不同层次的理解——不同的详细程度、不同的表述方式、不同的感知和不同的观点。</p><h3 id="分析问题和机会" tabindex="-1">分析问题和机会 <a class="header-anchor" href="#分析问题和机会" aria-label="Permalink to &quot;分析问题和机会&quot;">​</a></h3><p>除了了解当前系统以外，项目团队必须同系统所有者和系统用户一起分析问题和机会。</p><p>常见的一种记录因果分析的文档格式如图所示。 <img src="'+r+'" alt="ruankao_2026-08-26_212614_394.png" loading="lazy"></p><h3 id="制定系统改进目标" tabindex="-1">制定系统改进目标 <a class="header-anchor" href="#制定系统改进目标" aria-label="Permalink to &quot;制定系统改进目标&quot;">​</a></h3><p>系统改进目标应该是精确地、可度量地定义新系统预期的业务性能陈述。它可能受到约束条件的调节，约束条件分为以下4类：进度、成本、技术、政策。</p><h3 id="汇报调查结果和建议" tabindex="-1">汇报调查结果和建议 <a class="header-anchor" href="#汇报调查结果和建议" aria-label="Permalink to &quot;汇报调查结果和建议&quot;">​</a></h3><p>问题分析阶段需要以一个沟通任务作为总结。我们必须向业务团队汇报调查结果和建议。</p><h2 id="业务流程分析" tabindex="-1">业务流程分析 <a class="header-anchor" href="#业务流程分析" aria-label="Permalink to &quot;业务流程分析&quot;">​</a></h2><h3 id="业务流程分析概述" tabindex="-1">业务流程分析概述 <a class="header-anchor" href="#业务流程分析概述" aria-label="Permalink to &quot;业务流程分析概述&quot;">​</a></h3><blockquote><p>业务流程分析的步骤</p></blockquote><p>业务流程分析的具体步骤如下：通过调查掌握基本情况，描述现有业务流程，确认现有业务流程，对业务流程进行分析，发现问题并提出解决方案，提出优化后的业务流程。</p><blockquote><p>业务流程分析的方法</p></blockquote><p>业务流程分析的主要方法有价值链分析法、客户关系分析法、供应链分析法、基于 ERP 的分析法和业务流程重组等。</p><h3 id="业务流程图" tabindex="-1">业务流程图 <a class="header-anchor" href="#业务流程图" aria-label="Permalink to &quot;业务流程图&quot;">​</a></h3><h3 id="业务活动图" tabindex="-1">业务活动图 <a class="header-anchor" href="#业务活动图" aria-label="Permalink to &quot;业务活动图&quot;">​</a></h3><h3 id="业务流程建模-bpm" tabindex="-1">业务流程建模(BPM) <a class="header-anchor" href="#业务流程建模-bpm" aria-label="Permalink to &quot;业务流程建模(BPM)&quot;">​</a></h3><p>业务流程建模（BPM） 是对业务流程进行表述的方式，它是过程分析与重组的重要基础，这种表述方式大大优化了软件开发和运行效率。</p><h2 id="数据与数据流程分析" tabindex="-1">数据与数据流程分析 <a class="header-anchor" href="#数据与数据流程分析" aria-label="Permalink to &quot;数据与数据流程分析&quot;">​</a></h2><h3 id="数据流的内涵" tabindex="-1">数据流的内涵 <a class="header-anchor" href="#数据流的内涵" aria-label="Permalink to &quot;数据流的内涵&quot;">​</a></h3><p>数据流表示到一个过程的数据输入，或者来自一个过程的数据或信息输出，其中，过程响应输入并产生输出。</p><p>通常情况下，数据流包括以下几个方面:</p><ul><li>(1)数据源:指数据流的来源，也称为数据流入口。数据源可以是外部环境、其他系统、人员操作等。</li><li>(2)数据传输:指数据从数据源经过一定的传输方式到达目标位置的过程。数据传输方式可以是直接传输、存储传输、批量传输等。</li><li>(3)数据转换:指数据在传输过程中的转换和处理。数据转换可以是数据格式转换、数据清洗、数据整合、数据加工等。</li><li>(4)数据存储:指数据在系统内部被存储的过程。数据存储可以是在数据库、文件系统、内存中等。</li><li>(5)数据输出:指数据从系统中输出到目标位置的过程，也称为数据流出口。数据输出可以是向其他系统输出、输出到人员操作界面、输出到打印机等。</li></ul><h3 id="逻辑数据流与规则" tabindex="-1">逻辑数据流与规则 <a class="header-anchor" href="#逻辑数据流与规则" aria-label="Permalink to &quot;逻辑数据流与规则&quot;">​</a></h3><p>逻辑数据流是指在系统中进行数据处理的过程中，数据在逻辑上的流动路径和方式。它描述了数据在系统中的输入、处理、转换和输出等过程，以及数据处理的逻辑关系。</p><h3 id="数据流的守恒" tabindex="-1">数据流的守恒 <a class="header-anchor" href="#数据流的守恒" aria-label="Permalink to &quot;数据流的守恒&quot;">​</a></h3><p>数据流的守恒是指在系统中，数据在流动的过程中总量始终保持不变的原则。它是数据流分析中的一个重要概念，用于确保数据在系统中的正确性和完整性。</p><h3 id="数据流图-dfd" tabindex="-1">数据流图(DFD) <a class="header-anchor" href="#数据流图-dfd" aria-label="Permalink to &quot;数据流图(DFD)&quot;">​</a></h3><p>数据流图 （DFD） 是一种用于描述系统功能的图形化工具。它通过一组符号和规则，描述了系统内部各个功能模块之间的数据流动情况，帮助系统分析师和软件设计师更好地理解系统的功能和交互过程。</p><p>数据流图主要由4种符号组成:</p><ul><li>(1)数据流(Data Flow):用箭头表示，表示数据在不同功能模块之间的流动情况。数据流可以是物理数据(如文件、磁带等)或逻辑数据(如数据结构、数据库等)。</li><li>(2)进程(Process):用圆角矩形表示，表示系统中的功能模块或处理过程。进程可以是系统的输入或输出，也可以是系统内部的处理过程。</li><li>(3)数据存储(Data Store):用长方形表示，表示系统中的数据存储设备，如文件、数据库等。数据存储可以是物理存储设备或逻辑存储设备。</li><li>(4)外部实体(External Entity):用矩形表示，表示系统外部的实体，如人员、设备、其他系统等。外部实体可以向系统提供数据或从系统中获取数据。</li></ul><p>数据流图的优点和缺点如下图所示。 <img src="'+i+'" alt="ruankao_2026-08-26_214932_098.png" loading="lazy"></p><h3 id="物理数据流图" tabindex="-1">物理数据流图 <a class="header-anchor" href="#物理数据流图" aria-label="Permalink to &quot;物理数据流图&quot;">​</a></h3><p>物理数据流图建模作为信息系统一部分实现的技术设计决策和人为设计决策，将同那些实际构造和实现系统的人沟通技术选择和其他设计决策。</p><h3 id="数据汇总分析" tabindex="-1">数据汇总分析 <a class="header-anchor" href="#数据汇总分析" aria-label="Permalink to &quot;数据汇总分析&quot;">​</a></h3><p>数据汇总分析是指对一组数据进行综合性的整理、归纳和分析，以求得数据之间的相互关系和趋势规律，并从中得出结论和建议。它是数据分析中的一种常见方法，用于帮助分析师更好地理解和利用数据，从而做出更加准确和有效的决策。</p><h3 id="数据属性分析" tabindex="-1">数据属性分析 <a class="header-anchor" href="#数据属性分析" aria-label="Permalink to &quot;数据属性分析&quot;">​</a></h3><p>在信息系统中，经常用属性的名和属性的值来描述事物某些方面的特征。一个事物的特征可能表现在多个方面，需要用多个属性的名和其相应的值来描述。例如，对某客户来说，其属性名和对应的属性值有客户编号、客户名、客户所在地区、法人代表、银行账号等。</p><p>数据的属性分析主要包括静态分析和动态分析。</p><h3 id="数据流程分析" tabindex="-1">数据流程分析 <a class="header-anchor" href="#数据流程分析" aria-label="Permalink to &quot;数据流程分析&quot;">​</a></h3><p>数据流程是指在系统中产生、传输、加工处理、使用、存储的过程，数据流程分析把数据在企业内部的流动情况抽象地独立出来，舍去了具体的企业组织结构、信息载体、物质、材料等，单从数据流动过程来考查实际业务的数据处理模式。</p><p>数据流程分析的目的是要发现和解决数据流通中的问题，例如 数据流程不畅、前后数据不匹配、数据处理过程不合理、输入输出不平衡等。</p><h2 id="系统可行性分析" tabindex="-1">系统可行性分析 <a class="header-anchor" href="#系统可行性分析" aria-label="Permalink to &quot;系统可行性分析&quot;">​</a></h2><p>可行性分析也称为可行性研宄，是所有项目投资、工程建设或重大改革在开始阶段必须进行的一项工作。它是经济活动中经常使用的一种决策程序和手段，也是投资前的必要环节。</p><p>可行性研宄必须从系统总体出发，对技术、经济、执行等多个方面进行分析和论证，以确定信息系统建设项目是否可行，为正确进行投资决策提供科学依据。</p><h3 id="可行性评价标准" tabindex="-1">可行性评价标准 <a class="header-anchor" href="#可行性评价标准" aria-label="Permalink to &quot;可行性评价标准&quot;">​</a></h3><p>在信息系统建设项目中，可行性研究通常从经济可行性、技术可行性、法律可行性和用户使用可行性4个方面来进行分析，其中经济可行性通常被认为是项目的底线。</p><h3 id="可行性研究的步骤" tabindex="-1">可行性研究的步骤 <a class="header-anchor" href="#可行性研究的步骤" aria-label="Permalink to &quot;可行性研究的步骤&quot;">​</a></h3><p>具体来说，可行性研究工作可以分为以下8个步骤。</p><h3 id="可行性研究报告" tabindex="-1">可行性研究报告 <a class="header-anchor" href="#可行性研究报告" aria-label="Permalink to &quot;可行性研究报告&quot;">​</a></h3><p>可行性研宄报告是项目初期策划的结果，它分析了项目的要求、目标和环境，提出了几种可供选择的方案，并从技术、经济、法律等各方面进行了可行性分析。</p><p>可行性研究报告是项目决策的依据，也可作为系统建设方案或投标书等文件的基础。</p><h2 id="成本效益分析" tabindex="-1">成本效益分析 <a class="header-anchor" href="#成本效益分析" aria-label="Permalink to &quot;成本效益分析&quot;">​</a></h2><p>成本效益分析是通过比较信息系统建设的全部成本和效益来评估项目价值的一种方法，它作为一种经济可行性分析的方法，将项目的所有成本和收益一一列出，并进行量化。</p><p>成本效益 分析的目的是从经济角度分析建设一个特定的新系统是否划算，首先要估算待建设系统的成本，然后与可能取得的收益进行比较与权衡，从而帮助决策人员正确地做出是否立项的决定。</p><h3 id="成本和收益" tabindex="-1">成本和收益 <a class="header-anchor" href="#成本和收益" aria-label="Permalink to &quot;成本和收益&quot;">​</a></h3><h3 id="净现值分析" tabindex="-1">净现值分析 <a class="header-anchor" href="#净现值分析" aria-label="Permalink to &quot;净现值分析&quot;">​</a></h3><h3 id="投资回收期与投资回报率" tabindex="-1">投资回收期与投资回报率 <a class="header-anchor" href="#投资回收期与投资回报率" aria-label="Permalink to &quot;投资回收期与投资回报率&quot;">​</a></h3><h2 id="系统方案建议" tabindex="-1">系统方案建议 <a class="header-anchor" href="#系统方案建议" aria-label="Permalink to &quot;系统方案建议&quot;">​</a></h2><p>根据10.7.2小节的介绍，在可行性研究的第5个步骤中，系统分析师应该从系统的逻辑模型出发，提出若干个系统解决方案，对每个候选方案进行分析，描述每个方案的成本和效益、优点和缺点。</p><h3 id="候选方案的可行性评价" tabindex="-1">候选方案的可行性评价 <a class="header-anchor" href="#候选方案的可行性评价" aria-label="Permalink to &quot;候选方案的可行性评价&quot;">​</a></h3><p>在对众多的候选方案进行可行性评价时，可以使用候选系统方案矩阵和可行性分析矩阵两种工具。</p><h4 id="候选系统方案矩阵" tabindex="-1">候选系统方案矩阵 <a class="header-anchor" href="#候选系统方案矩阵" aria-label="Permalink to &quot;候选系统方案矩阵&quot;">​</a></h4><h4 id="可行性分析矩阵" tabindex="-1">可行性分析矩阵 <a class="header-anchor" href="#可行性分析矩阵" aria-label="Permalink to &quot;可行性分析矩阵&quot;">​</a></h4><h3 id="系统建议方案报告" tabindex="-1">系统建议方案报告 <a class="header-anchor" href="#系统建议方案报告" aria-label="Permalink to &quot;系统建议方案报告&quot;">​</a></h3><p>作为一个正式文档，系统建议方案报告至少应该包含以下内容:</p><ul><li>(1)前置部分:包括标题、目录和摘要。摘要部分以1~2页的篇幅总结整个系统建议方案报告，提供系统方案中的重要时间、地点、人物、原因，以及系统方案是如何实现的等信息。因为多数高层管理人员没有时间读完整个报告，他们可能只阅读摘要。因此，摘要部分显得特别重要。</li><li>(2)系统概述:包括系统建议方案报告的目的、对问题的陈述、项目范围和报告内容的叙述性解释。</li><li>(3)系统研究方法:简要地解释系统建议方案报告中包含的信息是如何得到的，研究工作是如何进行的。例如，通过各种调查技术获取用户初步需求，通过座谈和观察获取现有系统的资料等。</li><li>(4)候选系统方案及其可行性分析:系统阐述每个候选系统方案，并进行可行性评价。</li><li>(5)建议方案:在对各个候选系统方案进行可行性评价之后，通常会推荐一个解决方案，并且要给出推荐该解决方案的理由。</li><li>(6)结论:简要地描述摘要的内容，再次指出系统开发的目标和所建议的系统方案。同时，需要再次强调项目的必要性和可行性，以及系统建议方案报告的价值。</li><li>(7)附录:系统分析师认为阅读者可能会感兴趣的所有信息，但这些信息对于理解系统建议方案报告的内容来说不是必要的。</li></ul>',118)])])}const k=e(h,[["render",p]]);export{q as __pageData,k as default};
